"""Field help with matching English, German and Hungarian translations."""
from ui_i18n import TRANSLATIONS
FIELDS={}
def field(key,en,de,hu):FIELDS[key]=en;TRANSLATIONS[en]=(de,hu)
field('device_id','Generated automatically on first save; read-only. Existing IDs and links are preserved.','Dauerhafte eindeutige Kennung, beim ersten Speichern automatisch erzeugt; schreibgeschützt. Bestehende IDs und Verknüpfungen bleiben erhalten.','Első mentéskor automatikusan létrejön; csak olvasható. Meglévő azonosítók és kapcsolatok megmaradnak.')
field('name','Required, unique descriptive name. Maximum length: 100 characters. Unicode characters, including Hungarian/German accents, are allowed. Capitalization and extra spaces do not distinguish duplicate names. Suggested: backup-server-office-01. This is separate from hostname.','Eindeutiger beschreibender Pflichtname. Maximal 100 Zeichen. Unicode einschließlich ungarischer/deutscher Akzente erlaubt. Groß-/Kleinschreibung und zusätzliche Leerzeichen unterscheiden keine Namen. Beispiel: backup-server-office-01. Vom Hostnamen getrennt.','Kötelező, egyedi leíró név. Legfeljebb 100 karakter. Unicode, magyar/német ékezetek is megengedettek. Betűméret és extra szóköz nem különbözteti meg a neveket. Példa: backup-server-office-01. Gépnévtől külön mező.')
field('source','Required evidence source for this device record, such as a label, invoice or your own report.','Pflichtquelle dieses Datensatzes, etwa Typenschild, Rechnung oder eigene Angabe.','Az eszközrekord kötelező forrása: adattábla, számla vagy saját közlés.')
field('purchase_date','Date of purchase. Uncheck Known if unknown; use the calendar for a valid date.','Kaufdatum. Bekannt abwählen, falls unbekannt; Kalender für gültiges Datum.','Vásárlás dátuma. Ismeretlennél kapcsold ki az Ismert jelölést; érvényes dátumhoz naptár.')
field('installation_date','Device commissioning date. Component installation history is stored separately.','Inbetriebnahmedatum des Geräts. Komponenten-Einbauverlauf separat gespeichert.','Eszköz üzembe helyezése. Alkatrészek beszereléstörténete külön tárolva.')
field('scrapped_date','Date disposed of as waste, not merely retired or switched off. Leave unknown when not established.','Datum der Abfallentsorgung, nicht nur Stilllegung oder Abschaltung. Ungeklärtes unbekannt lassen.','Hulladékként selejtezés dátuma, nem kivonás vagy kikapcsolás. Ha nem ismert, hagyd ismeretlenül.')
field('purchase_price','Exact purchase amount with a decimal point, for example 129.90. Price and currency must both be supplied or both unknown.','Exakter Kaufbetrag mit Dezimalpunkt, etwa 129.90. Preis und Währung zusammen oder beide unbekannt.','Pontos vételár tizedesponttal, például 129.90. Ár és pénznem együtt, vagy mindkettő ismeretlen.')
field('purchase_currency','Choose or type a three-letter uppercase currency code. Stored codes such as EUR and HUF are language independent.','Dreistelligen Großbuchstaben-Währungscode wählen/eingeben. EUR/HUF sind sprachunabhängig.','Három nagybetűs pénznemkód választása/beírása. EUR/HUF nyelvfüggetlen.')
field('current_state','Lifecycle state, such as in use or spare. It is separate from physical condition and power state.','Lebenszyklusstatus, etwa in use oder spare. Getrennt von physischem Zustand und Stromstatus.','Életciklusállapot, például in use vagy spare. Külön a fizikai állapottól és bekapcsoltságtól.')
field('physical_condition','Functional condition, such as working or faulty. Do not infer it from the device role.','Funktionszustand, etwa working oder faulty. Nicht aus der Rolle ableiten.','Működési állapot, például working vagy faulty. Ne következtesd szerepből.')
field('device_type','One physical device type. Its group follows automatically; role and assembly membership are separate.','Ein physischer Gerätetyp. Gruppe folgt automatisch; Rolle und Baugruppe sind getrennt.','Egy fizikai eszköztípus. Csoport automatikusan követi; szerep és szerelvény külön.')
TIPS={}
def tip(key,en,de,hu):TIPS[key]=en;TRANSLATIONS[en]=(de,hu)
tip('type_group','Narrow the device-type list. A group alone is not saved; select a type or leave both unknown.','Typauswahl eingrenzen. Gruppe allein nicht gespeichert; Typ wählen oder unbekannt lassen.','Típuslista szűkítése. Csoport önmagában nem mentődik; válassz típust vagy hagyd ismeretlenül.')
tip('search','Filter saved devices by ID, name, type, group, lifecycle, condition or recorded interface/protocol.','Gespeicherte Geräte nach ID, Name, Typ, Gruppe, Lebenszyklus, Zustand oder Schnittstelle/Protokoll filtern.','Mentett eszközök szűrése ID, név, típus, csoport, állapot vagy interfész/protokoll alapján.')
tip('filter','Filters combine with the search text. They do not change device records.','Filter wirken gemeinsam mit Suchtext. Keine Änderung an Gerätedaten.','Szűrők keresőszöveggel együtt hatnak. Nem változtatják meg a rekordokat.')
tip('manage_connections','Edit the shared interface/protocol catalogue, not this device. Add a new choice or rename one for every assigned device. Use the checkboxes to assign choices to a device.','Gemeinsamen Schnittstellen-/Protokollkatalog bearbeiten, nicht dieses Gerät. Neue Auswahl oder Umbenennung für alle Geräte; Zuordnung per Häkchen.','Közös interfész/protokoll-katalógus, nem az eszköz szerkesztése. Új választás vagy átnevezés minden érintettnél; hozzárendelés a jelölőnégyzetekkel.')
tip('supported','Unknown means not established; none means known absent; recorded below requires at least one checked supported capability.','Unbekannt bedeutet ungeklärt, keine bedeutet nachweislich abwesend; unten erfasst erfordert mindestens ein Häkchen.','Ismeretlen: nem tisztázott; nincs: igazolt hiány; alább rögzítve: legalább egy támogatott jelölés.')
tip('usage','Capabilities used in the recorded configuration, not a live connection test. In-use choices must also be supported.','In der erfassten Konfiguration verwendete Fähigkeiten, kein Live-Test. Verwendung setzt Unterstützung voraus.','Rögzített konfigurációban használt képesség, nem élő kapcsolatvizsgálat. Használt csak támogatott lehet.')
tip('assessment_source','Recommended evidence source. If missing, a warning is shown but saving is allowed.','Empfohlene Belegquelle. Fehlt sie, erscheint eine Warnung; Speichern bleibt möglich.','Javasolt bizonyítékforrás. Hiányakor figyelmeztetés jelenik meg, de menteni lehet.')
tip('date','Check Known to enable the calendar. Uncheck it to store no date; the disabled displayed date is not saved.','Bekannt aktiviert den Kalender; abgewählt wird kein Datum gespeichert. Grau angezeigtes Datum nicht gespeichert.','Ismert bekapcsolása engedélyezi a naptárat. Kikapcsolva nincs dátum; a szürkén mutatott dátum nem mentődik.')
tip('photo_list','Attached photos for this saved device. Double-click a thumbnail to open the original.','Anhänge dieses gespeicherten Geräts. Doppelklick öffnet Original.','Mentett eszköz fotómellékletei. Dupla kattintással eredeti kép.')
BUTTONS={
'New device':('Start a blank device form. Unsaved edits require confirmation before discarding.','Leeres Geräteformular starten; ungespeicherte Änderungen vor Verwerfen bestätigen.','Üres eszközűrlap; mentetlen változás eldobása előtt megerősítés.'),
'Refresh':('Reload saved devices and shared choice lists.','Gespeicherte Geräte und gemeinsame Auswahllisten neu laden.','Mentett eszközök és közös választék újratöltése.'),
'Full backup':('Create a verified ZIP containing the database and attached photo files. Automatic save snapshots contain only the database.','Geprüfte ZIP mit Datenbank und Fotos. Automatische Sicherungen enthalten nur Datenbank.','Ellenőrzött ZIP adatbázissal és fotókkal. Automatikus pillanatkép csak adatbázist tartalmaz.'),
'Manage types':('Add, rename or regroup shared device types; changes affect all devices using that type.','Gemeinsame Gerätetypen ergänzen/umbenennen/verschieben; betrifft alle zugeordneten Geräte.','Közös típus felvétele/átnevezése/áthelyezése; minden érintett eszközre hat.'),
'Save device':('Validate and save the form, dates and connectivity together, after a verified pre-save database backup.','Formular, Daten und Verbindungen nach geprüfter vorheriger Datenbanksicherung gemeinsam speichern.','Űrlap, dátumok és kapcsolatok ellenőrzött előzetes adatbázismentés után együtt mentődnek.'),
'Cancel changes':('Discard unsaved edits. Already saved records or photo attachments are not undone.','Ungespeicherte Änderungen verwerfen; bereits gespeicherte Daten/Fotos bleiben.','Mentetlen változás elvetése; már mentett adat/fotó nem vonódik vissza.'),
'Add photo…':('Copy a JPEG/PNG into managed local storage. Save the device first; attachments save immediately.','JPEG/PNG in lokale Verwaltung kopieren. Gerät zuerst speichern; Anhang sofort gespeichert.','JPEG/PNG másolása kezelt helyi tárolóba. Előbb eszközmentés; melléklet azonnal mentődik.'),
'Open image':('Open the selected original image in the built-in scrollable viewer.','Ausgewähltes Original im eingebauten Bildbetrachter öffnen.','Kijelölt eredeti kép megnyitása beépített görgethető nézetben.'),
'Detach':('Remove the selected photo association. Files remain for older backups; your source image is never deleted.','Fotozuordnung entfernen; Dateien für alte Sicherungen und Quelldatei bleiben.','Fotóhozzárendelés leválasztása; fájlok régi mentésekhez és forráskép megmarad.'),
'Manage connection choices…':(TIPS['manage_connections'],*TRANSLATIONS[TIPS['manage_connections']]),
'New choice':('Start adding a shared catalogue value.','Neue gemeinsame Auswahl anlegen.','Új közös katalógusérték felvétele.'),
'Save choice':('Save a shared choice; renaming updates every device assigned to it.','Gemeinsame Auswahl speichern; Umbenennung aktualisiert alle zugeordneten Geräte.','Közös érték mentése; átnevezés minden hozzárendelt eszközt frissít.'),
'New type':('Start adding a shared device type.','Neuen gemeinsamen Gerätetyp anlegen.','Új közös eszköztípus felvétele.'),
'Save type':('Save the type name and group; changing an existing definition affects all assigned devices.','Typ und Gruppe speichern; Änderungen gelten für alle zugeordneten Geräte.','Típus és csoport mentése; meglévő módosítása minden érintett eszközre hat.'),
'Close':('Close this dialog.','Diesen Dialog schließen.','A párbeszédablak bezárása.')}
for key,(en,de,hu) in BUTTONS.items():TRANSLATIONS[en]=(de,hu)

tip('type_name','Shared catalogue name; renaming changes every assigned device.','Gemeinsamer Katalogname; Umbenennung ändert alle zugeordneten Geräte.','Közös katalógusnév; átnevezés minden hozzárendelt eszközt érint.')
tip('manage_group','Choose an existing group or type a new group name.','Bestehende Gruppe wählen oder neuen Gruppennamen eingeben.','Válassz meglévő csoportot vagy írj új csoportnevet.')
tip('software_status','Unknown means not established. Not applicable requires evidence that this category does not apply. Recorded enables details. OS and firmware are independent.','Unbekannt bedeutet ungeklärt. Nicht zutreffend benötigt einen Nachweis. Erfasst aktiviert Details. Betriebssystem und Firmware sind unabhängig.','Ismeretlen: nem tisztázott. Nem alkalmazható: indokoltan nem vonatkozik rá. Rögzítve engedélyezi a részleteket. OS és firmware független.')
tip('os_family','Select the current OS family, if known. An OS name can be recorded without knowing its family. No family is inferred from device type.','Aktuelle Betriebssystemfamilie wählen, falls bekannt. Name ohne bekannte Familie möglich. Keine Ableitung aus Gerätetyp.','Jelenlegi OS-család, ha ismert. OS-név ismeretlen család mellett is rögzíthető. Eszköztípusból nem következtetünk.')
tip('os_name','Installed operating system or distribution name, such as arch linux or proxmox ve. This form records one current OS, not dual-boot history.','Installiertes Betriebssystem/Distribution, etwa arch linux oder proxmox ve. Ein aktuelles OS, kein Dual-Boot-Verlauf.','Telepített OS/disztribúció, például arch linux vagy proxmox ve. Egy jelenlegi OS-t rögzít, nem dual-boot történetet.')
tip('os_version','Record the installed version exactly as shown by the device. Leave unknown when unavailable; no online update-status check is performed.','Installierte Version genau wie am Gerät erfassen. Unbekannt lassen, falls fehlt; keine Online-Aktualitätsprüfung.','Telepített verzió pontosan a készülék szerint. Ha hiányzik, ismeretlen; nincs online frissítettségvizsgálat.')
tip('firmware_version','Firmware can apply to disks, routers or sensors even when an OS entry is not applicable. Record the actual installed version.','Firmware kann für Laufwerke, Router oder Sensoren gelten, auch ohne zutreffenden OS-Eintrag. Tatsächlich installierte Version erfassen.','Firmware lemezen, routeren vagy érzékelőn is lehet, akkor is, ha OS nem alkalmazható. Tényleges telepített verziót rögzíts.')
tip('software_source','Required when OS or firmware is recorded or not applicable. Use real device settings, command output, management interface or documented assessment.','Erforderlich bei erfasster oder nicht zutreffender Software. Echte Einstellungen, Befehlsausgabe, Oberfläche oder dokumentierte Bewertung.','Rögzített vagy nem alkalmazható szoftvernél kötelező. Valós beállítás, parancskimenet, kezelőfelület vagy dokumentált értékelés.')
tip('manual_title','Descriptive title, such as installation guide or service manual. Required for each reference.','Beschreibender Pflichttitel, etwa Installationsanleitung oder Servicehandbuch.','Leíró kötelező cím, például telepítési útmutató vagy szervizkézikönyv.')
tip('manual_url','HTTP/HTTPS link opened by your browser only on request. It is not downloaded or available offline automatically.','HTTP-/HTTPS-Link öffnet Browser nur auf Anforderung. Kein automatischer Download oder Offlinezugriff.','HTTP/HTTPS link csak kérésre böngészőben. Nincs automatikus letöltés vagy offline elérés.')
tip('manual_language','Document language code, such as en, de or hu; leave unknown blank. This does not change the application language.','Dokumentsprachcode en/de/hu; unbekannt leer. Ändert nicht die Programmsprache.','Dokumentum nyelvkódja en/de/hu; ismeretlen üres. Nem változtatja az alkalmazás nyelvét.')
tip('manual_edition','Edition, revision or document version exactly as printed, when known.','Ausgabe/Revision/Dokumentversion genau wie angegeben, falls bekannt.','Kiadás/revízió/verzió pontosan a dokumentum szerint, ha ismert.')
tip('manual_applicable_model','The model or models covered by the document; leave unknown blank. No model match is inferred.','Vom Dokument abgedeckte Modelle; unbekannt leer. Keine automatische Modellzuordnung.','Dokumentum érintett modelljei; ismeretlen üres. Nincs automatikus modellegyeztetés.')
tip('manual_source','Required source: manufacturer site, original packaging or other actual provenance.','Pflichtquelle: Herstellerseite, Originalbeilage oder tatsächliche Herkunft.','Kötelező forrás: gyártói oldal, eredeti melléklet vagy valós származás.')
tip('manual_notes','Optional notes about this document, including applicability or limitations.','Optionale Notizen über Anwendbarkeit/Grenzen.','Opcionális megjegyzés az alkalmazhatóságról/korlátokról.')
tip('manual_file','Copy a PDF up to 100 MiB into managed local storage. Your source file stays untouched. To replace a PDF, detach and add a new reference.','PDF bis 100 MiB kopieren; Quelle bleibt unverändert. Ersatz-PDF durch Entfernen/Neuanlegen zuordnen.','Legfeljebb 100 MiB PDF másolása kezelt tárhelyre; forrás változatlan. Cseréhez leválasztás és új felvétel.')
tip('manual_kind','Online link or local PDF. A saved reference keeps its kind; create a new one to change kind.','Online-Link oder lokale PDF. Art bleibt gespeichert; zum Wechsel neuen Verweis anlegen.','Online link vagy helyi PDF. Mentett típusa rögzített; váltáshoz új hivatkozás.')
tip('manual_list','Manuals linked to this device. Add, edit metadata, open or detach. Files remain separate from SQLite.','Handbücher dieses Geräts: hinzufügen, Metadaten ändern, öffnen, entfernen. Dateien außerhalb SQLite.','Eszköz kézikönyvei: hozzáadás, metaadatszerkesztés, megnyitás, leválasztás. Fájlok SQLite-on kívül.')
for key,tipkey in (('Add reference…','manual_kind'),('Edit reference…','manual_list'),('Open reference','manual_url'),('Detach reference','manual_file')):
    source=TIPS[tipkey];BUTTONS[key]=(source,*TRANSLATIONS[source])
# Extend the full-backup tooltip to cover manual files as well.
_source='Create a verified ZIP with the database, attached photos and local manuals. Automatic snapshots contain only the database.'
TRANSLATIONS[_source]=('Geprüfte ZIP mit Datenbank, Fotos und lokalen Handbüchern; automatische Sicherungen nur Datenbank.','Ellenőrzött ZIP adatbázissal, fotóval és helyi kézikönyvvel; automatikus pillanatkép csak adatbázis.')
BUTTONS['Full backup']=(_source,*TRANSLATIONS[_source])
field('purchased_at','Shop, marketplace or seller. Optional text; spelling suggestions never change it automatically.','Shop, Marktplatz oder Verkäufer. Optionaler Text; Schreibvorschläge ändern ihn niemals automatisch.','Bolt, piactér vagy eladó. Nem kötelező; a helyesírási javaslat nem módosítja automatikusan.')
field('source','Enter free-text evidence notes, or choose source references below. Existing source text is preserved. A saved device needs text or at least one selected device source.','Freie Quellennotizen eingeben oder unten Quellen wählen. Bestehender Text bleibt erhalten. Ein Gerät benötigt Text oder mindestens eine Gerätequelle.','Adj meg szabad szöveges forrásjegyzetet vagy válassz forrásokat lent. A meglévő szöveg megmarad. Mentett eszközhöz szöveg vagy legalább egy eszközforrás kell.')

field('location','Optional physical location, for example building / room / rack / shelf. Unicode allowed; maximum 200 characters. Leave unknown blank. This is not a network address or purchased-at value.','Optionaler physischer Standort, z. B. Gebäude / Raum / Rack / Regal. Unicode erlaubt; höchstens 200 Zeichen. Unbekanntes leer lassen. Keine Netzwerkadresse und kein Kaufort.','Opcionális fizikai hely, például épület / helyiség / rack / polc. Unicode megengedett; legfeljebb 200 karakter. Ismeretlen maradjon üres. Nem hálózati cím és nem vásárlási hely.')

field('manufacturer','Optional manufacturer or brand, up to 200 printable characters. Leave unknown blank; existing values are not inferred from the name.','Optionaler Hersteller oder Marke, bis 200 druckbare Zeichen. Unbekannt leer lassen; keine Ableitung aus Namen.','Opcionális gyártó/márka, legfeljebb 200 nyomtatható karakter. Ismeretlenül üres; névből nincs következtetés.')
field('model','Optional model name or model code, up to 200 printable characters. Capitalization is preserved.','Optionale Modellbezeichnung oder Modellcode, bis 200 druckbare Zeichen. Groß-/Kleinschreibung bleibt.','Opcionális modellnév/kód, legfeljebb 200 nyomtatható karakter. Kis-/nagybetű megmarad.')
field('serial_number','Optional serial number as text, up to 200 printable characters. Leading zeros, case and internal spacing are preserved; surrounding whitespace is trimmed. Not globally unique.','Optionale Seriennummer als Text, bis 200 druckbare Zeichen. Führende Nullen, Groß-/Kleinschreibung und innere Leerzeichen bleiben; äußere werden entfernt. Nicht global eindeutig.','Opcionális sorozatszám szövegként, max. 200 nyomtatható karakter. Kezdő nullák, betűméret és belső szóköz megmarad; szélső szóköz törlődik. Nem globálisan egyedi.')
